// Fragment A sets a result:
setFragmentResult("requestKey", bundleOf("selectedId" to id))

// Fragment B listens, decoupled from Fragment A entirely:
parentFragmentManager.setFragmentResultListener("requestKey", viewLifecycleOwner) { _, bundle ->
    val id = bundle.getString("selectedId")
}

override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
    viewLifecycleOwner.lifecycleScope.launch {
        viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
            viewModel.uiState.collect { render(it) }
        }
    }
}

// Show a dialog owned by this Fragment
MyDialogFragment().show(childFragmentManager, "confirm")

// Send a result to a sibling / parent screen
parentFragmentManager.setFragmentResult("requestKey", bundleOf("id" to 42))

// Receive a result from a nested child
childFragmentManager.setFragmentResultListener("childKey", viewLifecycleOwner) { _, bundle -> }

class AppFragmentFactory(private val repository: Repository) : FragmentFactory() {
    override fun instantiate(classLoader: ClassLoader, className: String): Fragment =
        when (loadFragmentClass(classLoader, className)) {
            ProfileFragment::class.java -> ProfileFragment(repository)
            else -> super.instantiate(classLoader, className)
        }
}

class MainActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        supportFragmentManager.fragmentFactory = AppFragmentFactory(repository) // before super
        super.onCreate(savedInstanceState)
    }
}
